#!/usr/bin/env python3
"""Build the machine-readable Rust rewrite coverage inventory.

Inputs:
* ``docs/rust/inventory/python-surface.json`` — generated by
  ``discover_python_surface.py`` from the pinned Python oracle.
* ``scripts/rust/inventory_model.py`` — curated contracts, workflows, slices.

Output: ``docs/rust/inventory/coverage.json``.  The output is deterministic
(sorted keys/collections) so review diffs show real scope changes.  It does
not claim completion: every unclassified command stays ``unresolved`` and every
unported behaviour stays ``absent``/``pending``.  The checker, not this builder,
decides whether the gates pass.

Development-only; never invoked by the Rust binary.
"""
from __future__ import annotations

import hashlib
import json
import re
import sys
import tomllib
from pathlib import Path

# Development tooling must not leave bytecode in the checkout.
sys.dont_write_bytecode = True
from typing import Any

import yaml

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path.insert(0, str(HERE))

import inventory_model as model  # noqa: E402

SURFACE_PATH = ROOT / "docs/rust/inventory/python-surface.json"
OUTPUT_PATH = ROOT / "docs/rust/inventory/coverage.json"
BASELINE_COMMIT = "9aed3a8012cb5eb22c0128b14d525039f95fea7a"


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _option_signature(param: dict[str, Any]) -> dict[str, Any]:
    return {
        "name": param.get("name"),
        "flags": param.get("flags", []),
        "secondary_flags": param.get("secondary_flags", []),
        "type": param.get("type"),
        "required": param.get("required"),
        "default": param.get("default"),
        "multiple": param.get("multiple"),
        "nargs": param.get("nargs"),
        "is_flag": param.get("is_flag"),
        "hidden": param.get("hidden"),
        "alias_for": param.get("alias_for"),
        "deprecated": param.get("deprecated"),
        "injected": param.get("injected"),
    }


def _argument_signature(param: dict[str, Any]) -> dict[str, Any]:
    return {
        "name": param.get("name"),
        "type": param.get("type"),
        "required": param.get("required"),
        "default": param.get("default"),
        "multiple": param.get("multiple"),
        "nargs": param.get("nargs"),
        "hidden": param.get("hidden"),
        "deprecated": param.get("deprecated"),
        "alias_for": param.get("alias_for"),
    }


def _surface_contract(node: dict[str, Any]) -> dict[str, Any]:
    """The exact parse-surface entry the checker compares against discovery."""
    return {
        "path": node["path"],
        "kind": node["kind"],
        "hidden": node.get("hidden", False),
        "deprecated": node.get("deprecated", False),
        "accepts_json": node.get("accepts_json", False),
        "context_settings": node.get("context_settings", {}),
        "options": sorted(
            (_option_signature(option) for option in node.get("options", [])),
            key=lambda item: (item["name"] or "", item["flags"]),
        ),
        "arguments": sorted(
            (_argument_signature(argument) for argument in node.get("arguments", [])),
            key=lambda item: item["name"] or "",
        ),
        "deprecated_flags": node.get("deprecated_flags", []),
    }


