def _parse_orchestrator_wire(root: Path) -> dict[str, Any]:
    envelope = (root / "src/specify_cli/orchestrator_api/envelope.py").read_text(encoding="utf-8")
    commands = (root / "src/specify_cli/orchestrator_api/commands.py").read_text(encoding="utf-8")
    version = re.search(r'CONTRACT_VERSION\s*=\s*"([^"]+)"', envelope)
    minimum = re.search(r'MIN_PROVIDER_VERSION\s*=\s*"([^"]+)"', envelope)
    codes = set(re.findall(r"^  ([A-Z][A-Z0-9_]+)\s+--", commands, re.MULTILINE))
    for path in sorted((root / "src/specify_cli/orchestrator_api").glob("*.py")):
        text = path.read_text(encoding="utf-8")
        codes.update(re.findall(r'(?:_fail\([^,]+,\s*|error_code\s*=\s*)"([A-Z][A-Z0-9_]{2,})"', text))
    codes = sorted(codes)
    return {
        "kind": "orchestrator_api_envelope",
        "contract_version": version.group(1) if version else None,
        "minimum_provider_version": minimum.group(1) if minimum else None,
        "transport": f"spec-kitty.orchestrator-api/{version.group(1)}" if version else None,
        "always_json": True,
        "required_keys": [
            "contract_version",
            "command",
            "timestamp",
            "correlation_id",
            "success",
            "error_code",
            "data",
        ],
        "error_codes": codes,
    }


def _parse_uv_lock(root: Path) -> list[dict[str, Any]]:
    data = tomllib.loads((root / "uv.lock").read_text(encoding="utf-8"))
    wanted = {
        "spec-kitty-events": "external events contract package",
        "spec-kitty-tracker": "external tracker contract package",
        "typer": "CLI framework whose vendored Click surface is observable",
        "click": "Click parameter/command surface",
        "pydantic": "event/decision model validation",
        "pyyaml": "YAML read compatibility",
        "ruamel.yaml": "comment-preserving YAML writes",
        "jsonschema": "schema validation",
        "cryptography": "encrypted auth/session storage",
        "mcp": "MCP companion/client surface",
    }
    rows = []
    for package in data.get("package", []):
        name = package.get("name")
        if name in wanted:
            rows.append(
                {
                    "name": name,
                    "version": package.get("version"),
                    "source": package.get("source"),
                    "role": wanted[name],
                }
            )
    return sorted(rows, key=lambda row: row["name"])


def _parse_pins(root: Path) -> list[dict[str, Any]]:
    rows = []
    for path in sorted((root / "pins").glob("*.source.yaml")):
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
        rows.append(
            {
                "service": data.get("service"),
                "repository": data.get("repository"),
                "tag": data.get("tag"),
                "commit": data.get("commit"),
                "protocol_versions": data.get("protocol_versions", []),
                "requires_core": data.get("requires_core"),
                "file": path.relative_to(root).as_posix(),
                "assets": sorted((data.get("assets") or {}).keys()),
            }
        )
    return sorted(rows, key=lambda row: row["service"] or "")


def _parse_oracle_versions(python_rows: list[dict[str, Any]]) -> dict[str, Any]:
    """Compare the oracle interpreter's installed packages with uv.lock."""
    import importlib.metadata as metadata

    rows = []
    mismatches = []
    for row in python_rows:
        name = row["name"]
        try:
            installed = metadata.version(name)
        except metadata.PackageNotFoundError:
            installed = None
        rows.append({"name": name, "lock_version": row["version"], "installed_version": installed})
        if installed is not None and installed != row["version"]:
            mismatches.append(
                {
                    "name": name,
                    "lock_version": row["version"],
                    "installed_version": installed,
                    "wire_contract": name
                    in {"spec-kitty-events", "spec-kitty-tracker"},
                }
            )
    return {
        "interpreter": sys.executable,
        "python_version": sys.version.split()[0],
        "packages": sorted(rows, key=lambda item: item["name"]),
        "lock_mismatches": sorted(mismatches, key=lambda item: item["name"]),
    }


def _toolchain(root: Path) -> dict[str, Any]:
    data = tomllib.loads((root / "rust-toolchain.toml").read_text(encoding="utf-8"))
    toolchain = data.get("toolchain", {})
    return {
        "channel": toolchain.get("channel"),
        "profile": toolchain.get("profile"),
        "components": toolchain.get("components", []),
    }


def _status_defaults() -> dict[str, Any]:
    return {
        "implementation": {"status": "absent", "native_refs": [], "notes": ""},
        "conformance": {"status": "none", "refs": []},
        "review": {"status": "none", "refs": [], "independent": False},
        "performance": {"status": "not_measured", "workload_ids": []},
    }


def _apply_status(entry: dict[str, Any], implementation: dict[str, Any] | None = None) -> None:
    defaults = _status_defaults()
    for key in ("implementation", "conformance", "review", "performance"):
        entry.setdefault(key, defaults[key])
    if implementation:
        entry["implementation"] = {**entry["implementation"], **implementation}


def _aggregate_children(entries: list[dict[str, Any]], paths: list[list[str]]) -> dict[str, Any]:
    child_entries = [
        entry for entry in entries if entry["kind"] == "cli_leaf" and entry["path"][: len(paths)] == paths
    ]
    if not child_entries:
        return {"status": "absent", "native_refs": [], "notes": "group has no leaves"}
    statuses = [entry["implementation"]["status"] for entry in child_entries]
    if all(status == "implemented" for status in statuses):
        status = "implemented"
    elif any(status != "absent" for status in statuses):
        status = "partial"
    else:
        status = "absent"
    return {
        "status": status,
        "native_refs": sorted({ref for entry in child_entries for ref in entry["implementation"].get("native_refs", [])}),
        "notes": f"aggregate of {len(child_entries)} leaves",
    }


def _preserve_native_extensions(existing: dict[str, Any]) -> list[dict[str, Any]]:
    previous = {item.get("id"): item for item in existing.get("native_extensions", []) if item.get("id")}
    extensions = json.loads(json.dumps(model.NATIVE_EXTENSIONS))
    for extension in extensions:
        prior = previous.get(extension.get("id"))
        if prior:
            for key in ("implementation", "conformance", "review"):
                if key in prior:
                    extension[key] = prior[key]
    return extensions


def _load_existing(path: Path | None) -> dict[str, Any]:
    if path is None or not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _preserve_entry_evidence(entries: list[dict[str, Any]], existing: dict[str, Any]) -> None:
    """Keep evidence/status across regeneration; never keep structural scope."""
    previous = {entry.get("id"): entry for entry in existing.get("entries", []) if entry.get("id")}
    for entry in entries:
        before = previous.get(entry["id"])
        if not before:
            continue
        for key in ("implementation", "conformance", "review", "performance"):
            if key in before:
                entry[key] = before[key]
        if entry.get("kind") == "workflow":
            for key in ("status", "acceptance_tests", "differential_tests", "refusal_tests", "interruption_tests", "concurrency_tests", "user_content_tests", "review"):
                if key in before:
                    entry[key] = before[key]


def _preserve_performance(fresh: dict[str, Any], existing: dict[str, Any]) -> dict[str, Any]:
    before = existing.get("performance") or {}
    if not before:
        return fresh
    for key in ("status", "candidate", "harness", "aggregate", "startup"):
        if key in before:
            fresh[key] = before[key]
    previous_workloads = {item.get("id"): item for item in before.get("workloads", []) if item.get("id")}
    merged = []
    for workload in fresh.get("workloads", []):
        prior = previous_workloads.get(workload["id"])
        if prior:
            immutable = {key: workload[key] for key in ("id", "category", "required", "strict_equivalence", "notes") if key in workload}
            workload = {**prior, **immutable}
        merged.append(workload)
    fresh["workloads"] = merged
    return fresh


def build(surface: dict[str, Any], root: Path, existing_path: Path | None = None) -> dict[str, Any]:
    wire = _parse_orchestrator_wire(root)
    entries: list[dict[str, Any]] = []

    # Root CLI entry (global options and startup gates).
    root_node = surface["root"]
    root_entry = {
        "id": "CLI:",
        "kind": "cli_root",
        "title": "spec-kitty root command and startup gates",
        "path": [],
        "argv": ["spec-kitty"],
        "required": True,
        "mutates": True,
        "mutation_trigger": "startup bootstrap (global runtime assets, schema/legacy gates) before dispatch",
        "contract": {
            **model.CONTRACTS["project_init"],
            "class": "startup_gate",
            "writes": [
                "~/.kittify global runtime assets (ensure_runtime / agent commands / agent skills)",
                "project-local schema/legacy refusals before dispatch",
            ],
            "authority": [
                "src/specify_cli/__init__.py::main_callback",
                "src/specify_cli/runtime/bootstrap.py::ensure_runtime",
                "src/specify_cli/runtime/startup_assets.py",
                "src/specify_cli/migration/gate.py::check_schema_version",
                "src/specify_cli/migration/legacy_charter_gate.py",
            ],
            "source_refs": [root_node["callback"]["source_ref"]],
        },
        "wire": {"kind": "cli_json", "accepts_json": root_node.get("accepts_json", False)},
        "source_refs": [root_node["callback"]["source_ref"]],
        "test_refs": [],
        "surface": _surface_contract({**root_node, "kind": "root"}),
        "dependencies": ["STATE-PROJECT-INIT", "MIG-REGISTRY"],
        "notes": "The root callback writes global runtime assets before dispatch; it is not a pure dispatcher.",
    }
    _apply_status(
        root_entry,
        {
            "status": "partial",
            "native_refs": ["crates/sk-cli/src/main.rs"],
            "notes": "Rust has --project-root/--json and discovery; it has no runtime bootstrap, schema gate, legacy gate or upgrade notice.",
        },
    )
    entries.append(root_entry)

    # Groups.
    for group in surface["groups"]:
        if not group["path"]:
            continue
        entry = {
            "id": group["id"],
            "kind": "cli_group",
            "title": group.get("short_help") or group.get("help") or "/".join(group["path"]),
            "path": group["path"],
            "argv": group["argv"],
            "required": True,
            "mutates": False,
            "contract": dict(model.CONTRACTS["read_only"]),
            "wire": {"kind": "cli_group", "accepts_json": group.get("accepts_json", False)},
            "source_refs": group.get("source_refs", []),
            "test_refs": [],
            "surface": _surface_contract(group),
            "dependencies": [],
            "child_count": group.get("child_count", 0),
        }
        _apply_status(entry)
        entries.append(entry)

    # Leaves.
    for leaf in surface["leaves"]:
        path = "/".join(leaf["path"])
        family, mutates, trigger = model.family_for(path)
        contract = dict(model.CONTRACTS.get(family, model.CONTRACTS["unresolved"]))
        if family == "read_only":
            contract["source_refs"] = [leaf["callback"]["source_ref"]] if leaf["callback"]["source_ref"] else []
        elif contract["status"] == "documented":
            refs = list(contract.get("source_refs", []))
            callback_ref = leaf["callback"]["source_ref"]
            if callback_ref:
                refs = sorted({*refs, callback_ref})
            contract["source_refs"] = refs
        wire_contract: dict[str, Any] | None = None
        if leaf["path"][0] == "orchestrator-api":
            wire_contract = wire
        elif leaf.get("accepts_json"):
            wire_contract = {"kind": "cli_json", "accepts_json": True}
        entry = {
            "id": leaf["id"],
            "kind": "cli_leaf",
            "title": leaf.get("short_help") or (leaf.get("help") or "").splitlines()[0] if leaf.get("help") else path,
            "path": leaf["path"],
            "argv": leaf["argv"],
            "required": leaf["id"] not in model.EXCLUSIONS,
            "hidden": leaf.get("hidden", False),
            "deprecated": leaf.get("deprecated", False),
            "mutates": mutates,
            "mutation_trigger": trigger,
            "contract": contract,
            "wire": wire_contract,
            "alias_of": leaf.get("alias_of"),
            "shared_callback": leaf.get("shared_callback", []),
            "deprecated_flags": leaf.get("deprecated_flags", []),
            "source_refs": [leaf["callback"]["source_ref"]] if leaf["callback"]["source_ref"] else [],
            "test_refs": leaf.get("test_refs", {}).get("refs", []),
            "test_ref_count": leaf.get("test_refs", {}).get("count", 0),
            "surface": _surface_contract(leaf),
            "dependencies": _family_dependencies(family),
        }
        if leaf["id"] in model.EXCLUSIONS:
            entry["exclusion"] = {
                "class": "internal_sentinel",
                "reason": model.EXCLUSIONS[leaf["id"]],
            }
        _apply_status(entry, model.IMPLEMENTATION.get(leaf["id"]))
        entries.append(entry)

    # Contract, migration and workflow entries.
    for template in model.CONTRACT_ENTRIES:
        entry = json.loads(json.dumps(template))
        entry.setdefault("required", True)
        entry.setdefault("mutates", False)
        entry.setdefault("surface", None)
        entry.setdefault("path", None)
        entry.setdefault("argv", None)
        _apply_status(entry)
        entries.append(entry)

    for migration in surface.get("migrations", []):
        entry = {
            "id": f"MIG:{migration['id']}",
            "kind": "migration",
            "title": migration["description"],
            "required": True,
            "mutates": True,
            "contract": dict(model.CONTRACTS["migration"]),
            "wire": None,
            "source_refs": [migration["source_ref"]] if migration.get("source_ref") else [],
            "test_refs": [],
            "surface": None,
            "target_version": migration["target_version"],
            "migration_class": migration["class"],
            "runs_on_worktrees": migration["runs_on_worktrees"],
            "clone_local_effect": migration["clone_local_effect"],
            "dependencies": ["MIG-REGISTRY"],
        }
        _apply_status(entry)
        entries.append(entry)

    for workflow in model.WORKFLOWS:
        entry = json.loads(json.dumps(workflow))
        entry["kind"] = "workflow"
        entry["required"] = True
        entry["mutates"] = False
        entry["contract"] = dict(model.CONTRACTS["read_only"])
        entry["wire"] = None
        entry["surface"] = None
        entry["source_refs"] = []
        entry["test_refs"] = []
        _apply_status(entry)
        entries.append(entry)

    # Module census: every Python command-module file, including helpers.
    modules = []
    for module in surface.get("modules", []):
        registrations = module.get("registrations", {"commands": 0, "typers": 0})
        has_registrations = bool(registrations.get("commands") or registrations.get("typers"))
        if module.get("reachable_command_source"):
            status = "registered_command_source"
        elif has_registrations:
            status = "dynamically_registered"
        elif module.get("import_reachable"):
            status = "imported_helper"
        else:
            status = "unreferenced_helper"
        modules.append(
            {
                **module,
                "status": status,
                "top_level": Path(module["module"]).parent.as_posix()
                == "src/specify_cli/cli/commands",
            }
        )

    existing = _load_existing(existing_path)
    _preserve_entry_evidence(entries, existing)

    # Deterministic order and counts.
    entries.sort(key=lambda item: item["id"])

    kind_counts: dict[str, int] = {}
    status_counts: dict[str, int] = {}
    for entry in entries:
        kind_counts[entry["kind"]] = kind_counts.get(entry["kind"], 0) + 1
        impl = entry["implementation"]["status"]
        status_counts[impl] = status_counts.get(impl, 0) + 1

    unresolved = [
        entry["id"]
        for entry in entries
        if entry.get("contract", {}).get("status") == "unresolved"
    ]
    required = [entry for entry in entries if entry.get("required")]
    pending_impl = [entry["id"] for entry in required if entry["implementation"]["status"] != "implemented"]
    pending_conformance = [entry["id"] for entry in required if entry["conformance"]["status"] != "pass"]
    pending_review = [entry["id"] for entry in required if entry["review"]["status"] != "approved"]
    perf_workloads = json.loads(json.dumps(model.PERF_WORKLOADS))
    strict = [workload for workload in perf_workloads if workload["strict_equivalence"] and workload["required"]]
    perf_status = "pending"
    if strict and all(workload.get("status") == "pass" for workload in strict):
        perf_status = "pass"

    python_pins = _parse_uv_lock(root)
    dependencies = {
        "python": python_pins,
        "oracle": _parse_oracle_versions(python_pins),
        "services": _parse_pins(root),
        "rust": _toolchain(root),
    }

    slices = json.loads(json.dumps(model.SLICES))
    previous_slices = {item.get("id"): item for item in existing.get("delivery_slices", []) if item.get("id")}
    for slice_item in slices:
        if slice_item["id"] in previous_slices and "status" in previous_slices[slice_item["id"]]:
            slice_item["status"] = previous_slices[slice_item["id"]]["status"]
    done = {item["id"] for item in slices if item["status"] == "done"}
    for slice_item in slices:
        slice_item["ready"] = all(dep in done for dep in slice_item["depends_on"]) and slice_item["status"] != "done"
    ready_work = [item for item in sorted(slices, key=lambda item: item["priority"]) if item.get("ready")]

    counts = {
        "entries_total": len(entries),
        "entries_required": len(required),
        "entries_not_required": len(entries) - len(required),
        "entries_excluded": sum(1 for entry in entries if "exclusion" in entry),
        "by_kind": kind_counts,
        "by_implementation": status_counts,
        "mutating_entries": sum(1 for entry in entries if entry.get("mutates")),
        "documented_mutation_contracts": sum(
            1 for entry in entries if entry.get("mutates") and entry["contract"]["status"] == "documented"
        ),
        "unresolved_contracts": len(unresolved),
        "modules_total": len(modules),
        "modules_top_level": sum(1 for module in modules if module["top_level"]),
        "modules_registered": sum(1 for module in modules if module["status"] == "registered_command_source"),
        "modules_dynamically_registered": sum(
            1 for module in modules if module["status"] == "dynamically_registered"
        ),
        "modules_imported_helper": sum(1 for module in modules if module["status"] == "imported_helper"),
        "modules_unreferenced_helper": sum(1 for module in modules if module["status"] == "unreferenced_helper"),
        "cli": surface["counts"],
        "migrations": len(surface.get("migrations", [])),
        "workflows_total": len(model.WORKFLOWS),
        "workflows_required": len(model.REQUIRED_WORKFLOW_IDS),
        "perf_workloads_total": len(perf_workloads),
        "perf_workloads_required": len([w for w in perf_workloads if w["required"]]),
        "perf_workloads_strict": len(strict),
        "pending_implementation": len(pending_impl),
        "pending_conformance": len(pending_conformance),
        "pending_review": len(pending_review),
        "ready_slices": [item["id"] for item in ready_work],
    }

    performance = {
        "policy": model.PERF_POLICY,
        "status": perf_status,
        "baseline": {
            "commit": BASELINE_COMMIT,
            "python_version": surface["environment"]["sys_version"],
            "oracle_interpreter": "/home/exedev/.local/share/uv/tools/spec-kitty-cli/bin/python",
        },
        "candidate": {
            "rust_toolchain": _toolchain(root),
            "commit": None,
        },
        "harness": {
            "path": "benchmarks/rust/spkbench",
            "status": "incomplete",
            "notes": [
                "Workload registry exists; required strict-equivalence workloads are still 'pending'.",
                "Projection/startup workloads are diagnostic only and never gate evidence.",
            ],
        },
        "workloads": perf_workloads,
        "aggregate": {
            "status": "pending",
            "geometric_mean_speedup": None,
            "minimum_speedup": model.PERF_POLICY["minimum_speedup"],
            "max_per_workload_regression_fraction": model.PERF_POLICY[
                "max_per_workload_regression_fraction"
            ],
            "sample_count": 0,
            "evidence": None,
        },
        "startup": {
            "status": "pending",
            "excluded_from_gate": True,
            "workload_ids": ["startup.version", "startup.help"],
            "measurements": None,
        },
    }
    performance = _preserve_performance(performance, existing)

    inventory = {
        "schema_version": "1.0.0",
        "inventory_generator": "scripts/rust/build_inventory.py",
        "baseline": {
            "repository": "spec-kitty/spec-kitty",
            "commit": BASELINE_COMMIT,
            "surface_sha256": surface["baseline"]["surface_sha256"],
            "surface_schema_version": surface["schema_version"],
            "python_version": surface["environment"]["sys_version"],
            "typer_version": surface["environment"]["typer_version"],
            "click_version": surface["environment"]["click_version"],
        },
        "policy": {
            "completion_requires": [
                "every required CLI leaf/group/root has a native implementation with no Python runtime/FFI/stub",
                "every required contract, migration and workflow entry passes conformance and independent review",
                "every mutating entry has a documented mutation contract",
                "no unresolved classification remains",
                "all required workflows pass acceptance, differential, refusal, interruption, concurrency and user-content tests",
                "all required strict-equivalence performance workloads pass; geometric mean >= 3x; no >10% regression",
                "startup is measured separately and never counts toward the 3x aggregate",
                "cross-platform CI and packaging evidence are attached",
            ],
            "allowed_exclusions": {
                entry_id: model.EXCLUSIONS[entry_id] for entry_id in sorted(model.EXCLUSIONS)
            },
            "required_workflow_ids": sorted(model.REQUIRED_WORKFLOW_IDS),
            "required_perf_workload_ids": sorted(model.REQUIRED_PERF_WORKLOAD_IDS),
        },
        "counts": counts,
        "unresolved_entry_ids": unresolved,
        "entries": entries,
        "modules": sorted(modules, key=lambda item: item["module"]),
        "performance": performance,
        "workflows": [entry for entry in entries if entry["kind"] == "workflow"],
        "native_extensions": _preserve_native_extensions(existing),
        "dependencies": dependencies,
        "delivery_slices": slices,
        "ready_work": ready_work,
        "generated_from": {
            "surface_file": "docs/rust/inventory/python-surface.json",
            "surface_sha256": _sha256(SURFACE_PATH) if SURFACE_PATH.exists() else None,
            "model_file": "scripts/rust/inventory_model.py",
            "model_sha256": _sha256(HERE / "inventory_model.py"),
            "builder_sha256": _sha256(Path(__file__)),
        },
    }
    return inventory


def main(argv: list[str] | None = None) -> int:
    arguments = argv or sys.argv[1:]
    surface_path = Path(arguments[0]) if arguments else SURFACE_PATH
    if not surface_path.is_absolute():
        surface_path = ROOT / surface_path
    if not surface_path.exists():
        print(f"missing surface: {surface_path}; run discover_python_surface.py first", file=sys.stderr)
        return 2
    surface = _load_json(surface_path)
    evidence = surface.get("baseline", {}).get("surface_sha256")
    if not evidence:
        print("surface has no baseline.surface_sha256", file=sys.stderr)
        return 2
    inventory = build(surface, ROOT, existing_path=OUTPUT_PATH)
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT_PATH.write_text(
        json.dumps(inventory, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    print(
        f"wrote {OUTPUT_PATH.relative_to(ROOT)}: "
        f"{inventory['counts']['entries_total']} entries, "
        f"{inventory['counts']['entries_required']} required, "
        f"{inventory['counts']['unresolved_contracts']} unresolved"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
